let preferences={page:'dashboard',category:'contract',month:activationToday().slice(0,7),query:'',responsible:''};try{Object.assign(preferences,JSON.parse(localStorage.getItem('ps_cs_preferences')||'{}'))}catch{}function persistPreferences(){localStorage.setItem('ps_cs_preferences',JSON.stringify(preferences))}
const categories=[['contract','Aguardando contrato'],['implementation','Implantação'],['activation','Carteiras ativadas']];
function chooseCategory(category){preferences.category=category;persistPreferences();clients()}
function matchesSearch(c,q){return [c.fantasy,c.cnpj,c.ticket,c.implementationTicket,c.activationTicket].join(' ').toLowerCase().includes(q.toLowerCase())}
function visibleClients(){let category=preferences.category;return db.clients.filter(c=>(category==='all'||clientCategory(c).split(' ').includes(category))&&matchesSearch(c,preferences.query)&&(category==='activation'?matchesSeller(c):matchesResponsible(c))&&(category!=='activation'||!preferences.month||String(c.activationDate||'').startsWith(preferences.month))).sort((a,b)=>{let date=c=>category==='activation'?c.activationDate:category==='contract'?c.arrival:clientSortDate(c);return String(date(a)||'9999').localeCompare(String(date(b)||'9999'))||String(a.fantasy).localeCompare(String(b.fantasy),'pt-BR')})}
function clients(){if(!categories.some(([key])=>key===preferences.category)){preferences.category='contract';persistPreferences()}let cat=preferences.category;$('view').innerHTML=`<div class="client-tabs" role="group" aria-label="Etapas dos clientes">${categories.map(([key,label])=>`<button class="stage-tab ${categoryStageClass(key)} ${key===cat?'active':''}" aria-pressed="${key===cat}" onclick="chooseCategory('${key}')">${label}<b>${db.clients.filter(c=>clientCategory(c).split(' ').includes(key)).length}</b></button>`).join('')}</div><section class="panel client-panel"><h2 class="sr-only">${categories.find(x=>x[0]===cat)?.[1]||'Clientes'}</h2><div class="client-toolbar"><div class="client-search"><label class="sr-only" for="search">Buscar cliente</label><input id="search" type="search" placeholder="Buscar cliente, CNPJ ou ticket" value="${esc(preferences.query)}" oninput="filterClients()"></div><div class="${cat==='activation'?'hidden':''}"><label class="sr-only" for="responsibleFilter">Responsável CS</label><select id="responsibleFilter" aria-label="Responsável CS" onchange="filterClients()">${responsibleFilterOptions()}</select></div><button class="secondary ${cat==='activation'?'hidden':''}" onclick="preferences.responsible=db.user;persistPreferences();clients()">Minha carteira</button><button class="text-button" onclick="preferences.responsible='';preferences.seller='';preferences.query='';persistPreferences();clients()">Limpar filtros</button><select id="clientFilter" class="hidden"><option value="${cat}">${cat}</option></select><div id="activationMonthControls" class="activation-filters ${cat==='activation'?'':'hidden'}"><div><label class="sr-only" for="activationMonth">Mês e ano da ativação</label><input id="activationMonth" aria-label="Mês e ano da ativação" type="month" value="${esc(preferences.month)}" onchange="filterClients()"></div><div><label class="sr-only" for="sellerFilter">Vendedor</label><select id="sellerFilter" aria-label="Vendedor" onchange="preferences.seller=this.value;persistPreferences();renderClientRows()">${sellerOptions()}</select></div><button class="secondary" onclick="exportActivationReport()">Exportar CSV</button><button class="secondary" onclick="printActivationReport()">Imprimir / PDF</button></div></div><p id="filterCount" class="muted" aria-live="polite"></p><div class="tablewrap"><table class="client-table"><thead id="clientHeads"></thead><tbody id="clientRows"></tbody></table></div><div id="sellerSummary" class="${cat==='activation'?'':'hidden'}"></div></section>`;renderClientRows()}

function filterClients(){preferences.responsible=$('responsibleFilter').value;preferences.category=$('clientFilter').value;preferences.query=$('search').value;preferences.month=$('activationMonth').value;persistPreferences();renderClientRows()}
function nextAction(c){if(c.activationStatus==='Ativada')return 'Carteira ativada';if(c.implementationConfirmed)return 'Acompanhar implantação';if(!c.contractPortal)return 'Lançar contrato';if(!c.contractSigned)return 'Acompanhar assinatura';if(c.implementation)return 'Acompanhar implantação';return 'Iniciar implantação'}
function renderClientRows(){let cat=preferences.category,rows=visibleClients();let headers=cat==='activation'?['Cliente / CNPJ','Data da ativação','Ticket','Vendedor','Situação','Ações']:cat==='implementation'?['Cliente','Início','Tempo','Follow-up','Ações']:cat==='contract'?['Cliente / CNPJ','Chegada','Ticket inicial','Responsável','Próxima ação','Ações']:['Cliente / CNPJ','Etapa','Data de referência','Próxima ação','Ações'];$('clientHeads').innerHTML='<tr>'+headers.map(t=>'<th>'+t+'</th>').join('')+'</tr>';$('filterCount').textContent=`${rows.length} cliente(s)${cat==='activation'&&preferences.month?' ativado(s) em '+preferences.month.slice(5)+'/'+preferences.month.slice(0,4):''} · Mais antigos primeiro`;if(cat==='activation'){let summary=$('sellerSummary');if(!summary){$('filterCount').insertAdjacentHTML('afterend','<div id="sellerSummary"></div>');summary=$('sellerSummary')}summary.innerHTML=sellerSummaryTable(rows)}$('clientRows').innerHTML=rows.map(c=>{let a=statusAlert(c),cells=[`<strong>${esc(c.fantasy)}</strong><br><small class="client-cnpj">CNPJ ${esc(c.cnpj)}</small>`];if(cat==='activation')cells.push(fmt(c.activationDate),esc(c.activationTicket||'—'),esc(activationSellerName(c)),stageBadge('Concluído','Ativada'));else if(cat==='implementation')cells.push(fmt(c.implementation),c.implementation?String(Math.max(0,-daysTo(c.implementation)))+' dias':'Data não informada',a?`<span class="tag ${a.kind}" title="Prazo: ${fmt(a.due)}">${a.d<0?'Vencido':a.d===0?'Hoje':'No prazo'}</span>`:c.followupDone?'<span class="tag ok">Realizado</span>':'—');else if(cat==='contract')cells.push(fmt(c.arrival),esc(c.ticket||'—'),esc(c.responsible||'—'),esc(nextAction(c)));else cells.push(stageBadge(c.stage),fmt(clientSortDate(c)),esc(nextAction(c)));cells.push(`<div class="actions"><button class="secondary" onclick="detail('${c.id}')">Ver ficha</button>${clientCategory(c).split(' ').includes('implementation')?`<button onclick="activateWalletForm('${c.id}')">Ativar carteira</button>`:''}<details class="quick-actions"><summary>Ações</summary><div><button class="secondary" onclick="noteForm('${c.id}')">Registrar contato</button><button class="secondary" onclick="trainingForm('${c.id}')">Treinamento</button>${c.implementation&&!c.followupDone&&c.activationStatus!=='Ativada'?`<button class="secondary" onclick="followupForm('${c.id}')">Follow-up</button>`:''}<button class="secondary" onclick="openClient('${c.id}')">Editar</button></div></details></div>`);return '<tr>'+cells.map(x=>'<td>'+x+'</td>').join('')+'</tr>'}).join('')||`<tr><td class="empty" colspan="${headers.length}">Nenhum cliente encontrado. Ajuste o período ou a busca.</td></tr>`}
function activationReportRows(month,query){return db.clients.filter(c=>clientCategory(c).split(' ').includes('activation')&&(!month||String(c.activationDate||'').startsWith(month))&&matchesSearch(c,query)&&matchesSeller(c)).sort((a,b)=>String(a.activationDate||'9999').localeCompare(String(b.activationDate||'9999')))}
function printActivationReport(){let rows=activationReportRows(preferences.month,preferences.query);let period=preferences.month?preferences.month.slice(5)+'/'+preferences.month.slice(0,4):'Todos os períodos';$('printReport').innerHTML=`<h1>Relatório de ativações de carteira</h1><p>Precisão Sistemas · ${esc(period)} · Total: <b>${rows.length} clientes</b></p>${preferences.query?`<p>Busca aplicada: ${esc(preferences.query)}</p>`:''}<table><thead><tr>${['Cliente','CNPJ','Data da ativação','Ticket'].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.map(c=>'<tr>'+[c.fantasy,c.cnpj,fmt(c.activationDate),c.activationTicket].map(x=>'<td>'+esc(x||'—')+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="4">Nenhuma ativação no período.</td></tr>'}</tbody></table><p>Emitido em ${fmt(activationToday())}</p>`;window.print()}
// Account-scoped storage, optimistic concurrency and a preserved local recovery copy.
let cloudEtag=null,cloudReady=false,syncing=false,syncPromise=Promise.resolve(),cloudConflict=false,legacyMode=false,accountAuthKind='',teamIsShared=false,canRestoreBackups=false;
function syncMessage(message,retry=false){$('syncStatus').innerHTML=(teamIsShared?'<strong>Base compartilhada da equipe</strong> · ':'')+esc(message)+(cloudConflict?' <button class="secondary" onclick="recoverCloud()">Exportar cópia local e carregar nuvem</button>':'')+(retry?' <button class="secondary" onclick="queueCloud()">Tentar sincronizar</button>':'')}
function queueCloud(){if(!cloudReady||syncing||cloudConflict)return syncPromise;syncing=true;syncPromise=(async()=>{try{let auditWarning=false;while(localStorage.getItem('ps_cs_pending')==='1'){let snapshot=localStorage.getItem(KEY);syncMessage('Salvando na nuvem…');let response=await fetchTimed('/api/state',{method:'PUT',headers:{'Content-Type':'application/json',...(cloudEtag?{'If-Match':cloudEtag}:{'If-None-Match':'*'})},body:snapshot});if(response.status===409){cloudConflict=true;throw Error('Há alterações em outro dispositivo. Exporte seu backup antes de recarregar para conciliá-las.')}if(!response.ok){let failure=await response.json().catch(()=>({}));throw Error((failure.error||'Não foi possível salvar no servidor.')+' A cópia local está preservada.')}let result=await response.json();auditWarning=auditWarning||!!result.auditWarning;cloudEtag=result.etag;localStorage.setItem('ps_cs_cloud_etag',cloudEtag);if(localStorage.getItem(KEY)===snapshot)localStorage.removeItem('ps_cs_pending')}syncMessage(auditWarning?'✓ Dados salvos; o histórico adicional não foi confirmado. A cópia anterior permanece no backup.':'✓ Salvo no servidor às '+new Date().toLocaleTimeString('pt-BR'))}catch(error){syncMessage(error.message,!cloudConflict)}finally{syncing=false}})();return syncPromise}
async function refreshPage(){if(legacyMode){location.reload();return}await queueCloud();if(localStorage.getItem('ps_cs_pending')==='1'){toast('Há alterações locais pendentes. Use Backup antes de recarregar.');return}location.reload()}
async function logout(){if(legacyMode){sessionStorage.removeItem('ps_cs_legacy_session');location.reload();return}if(localStorage.getItem('ps_cs_pending')==='1'){toast('Aguarde a sincronização antes de sair.');return}if(accountAuthKind==='password'){let response=await fetch('/api/auth/logout',{method:'POST'});if(!response.ok){toast('Não foi possível sair. Tente novamente.');return}location.reload();return}location.href='/signout-with-chatgpt?return_to=%2F'}
function backup(){$('view').innerHTML=`<section class="panel"><h2>Dados e backup</h2>${!legacyMode&&canRestoreBackups?'<p><button onclick="loadServerBackups()">Backups automáticos do servidor</button></p><div id="serverBackups"></div>':''}<p><button class="secondary" onclick="inspectRecovery(true)">Procurar e recuperar cópias deste navegador</button></p><div id="recoveryResult"></div><p>${legacyMode?'Neste acesso, os registros ficam somente neste navegador. Exporte um backup antes de fechar a aba anônima.':'Os registros são salvos na nuvem da sua conta. A cópia local é mantida para recuperação.'}</p><div class="actions"><button onclick="exportBackup()">Exportar backup JSON</button><button class="secondary" onclick="$っ('importFile').click()">Importar backup</button><input id="importFile" class="hidden" type="file" accept="application/json,.json" onchange="importBackup(event)"></div><p class="hint">A importação acrescenta novos clientes e mantém os existentes. CNPJs já cadastrados são ignorados.</p></section><section class="panel"><h2>Integrações</h2><p>Os registros de ativação são controles desta Central. Não executam ações no Portal PS nem enviam notificações com o site fechado.</p></section>`.replace('$っ','$')}
async function boot(){if(sessionStorage.getItem('ps_cs_legacy_session')==='active'&&legacyAccess()){startLegacy();return}let auth=$('auth');auth.innerHTML=loadingMarkup();try{let response=await fetchTimed('/api/state',{cache:'no-store'});if(response.status===401){if(sessionStorage.getItem('ps_cs_legacy_session')==='active'&&legacyAccess()){startLegacy();return}showAccountScreen();return}if(!response.ok)throw Error('Não foi possível carregar os dados da sua conta.');let result=await response.json(),local=localStorage.getItem(KEY),pending=localStorage.getItem('ps_cs_pending')==='1';cloudEtag=result.etag;let localData=null;try{localData=JSON.parse(local)}catch{}if(result.authKind==='password'&&localStorage.getItem('ps_cs_local_owner')!==(result.scopeId||result.accountId)){if(localData)localStorage.setItem('ps_cs_account_backup_'+(localStorage.getItem('ps_cs_local_owner')||'legacy'),local);localData=null;pending=false;localStorage.removeItem('ps_cs_pending')}accountAuthKind=result.authKind||'chatgpt';teamIsShared=!!result.shared;canRestoreBackups=!!result.canRestore;isTeamAdmin=!!result.isAdmin;localStorage.setItem('ps_cs_local_owner',result.scopeId||result.accountId||'');if(localData&&localData.clients?.length&&!localStorage.getItem('ps_cs_recovery'))localStorage.setItem('ps_cs_recovery',local);if(localData&&localData.clients?.length&&result.data&&local!==JSON.stringify(result.data)&&!localStorage.getItem('ps_cs_previous'))localStorage.setItem('ps_cs_previous',local);if(result.data){if(pending&&localData&&localStorage.getItem('ps_cs_cloud_etag')===cloudEtag)db=localData;else{if(pending&&localData){cloudConflict=true;db=localData}else db=result.data}}else if(localData){db=localData;localStorage.setItem('ps_cs_pending','1')}db.user=result.name||db.user||'Responsável CS';if(!cloudConflict&&cloudEtag)localStorage.setItem('ps_cs_cloud_etag',cloudEtag);localStorage.setItem(KEY,JSON.stringify(db));cloudReady=true;auth.style.display='none';$('app').style.display='grid';$('who').textContent=result.displayName|| (db.user.includes('@')?'Minha conta':db.user);go(['dashboard','clients','alerts','reports','team','account','backup'].includes(preferences.page)?preferences.page:'dashboard');if(cloudConflict)syncMessage('Alterações locais pendentes e versão diferente na nuvem. Exporte seu backup para preservar as alterações.');else if(localStorage.getItem('ps_cs_pending')==='1')await queueCloud();else syncMessage('✓ Registros carregados do servidor');await maybeInitializeTeam()}catch(error){auth.innerHTML='<h1 class="auth-brand"><img src="/brand-logo-v1.svg" alt="Central CS" width="300" height="74"></h1><p>'+esc(error.message)+'</p><button onclick="boot()">Tentar novamente</button><p class="hint">Seus dados locais foram preservados.</p>'}}
window.addEventListener('beforeunload',e=>{if(localStorage.getItem('ps_cs_pending')==='1'){e.preventDefault();e.returnValue=''}});boot();

function recoverCloud(){exportBackup();if(!confirm('A cópia local foi exportada. Carregar os dados da nuvem? As alterações locais também permanecerão na cópia de recuperação deste navegador.'))return;localStorage.setItem('ps_cs_recovery',JSON.stringify(db));localStorage.removeItem('ps_cs_pending');location.reload()}

function automaticStage(c){if(c.activationStatus==='Ativada')return 'Concluído';if(c.implementation||c.implementationConfirmed)return 'Implantação';if(c.onboarding)return 'Onboarding';if(c.contractPortal||c.contractSigned)return 'Contrato';return 'Entrada'}
function updateStagePreview(form){let fd=new FormData(form),data={};for(const [key,value] of fd.entries())data[key]=value;let element=$('stagePreview');if(element){let stage=automaticStage({...db.clients.find(c=>c.id===form.dataset.clientId),...data});element.textContent=stage;element.className='notice '+stageClass(stage)}let warning=$('dateWarning');if(warning)warning.textContent=clientDateMessage(data)}
let reportYear=activationToday().slice(0,4),reportMonth='all';
function entriesInMonth(year,month){return db.clients.filter(c=>String(c.arrival||'').slice(0,7)===`${year}-${month}`).sort((a,b)=>String(a.arrival).localeCompare(String(b.arrival))||String(a.fantasy).localeCompare(String(b.fantasy),'pt-BR'))}
function entryReports(){let years=[...new Set([activationToday().slice(0,4),reportYear,...db.clients.map(c=>String(c.arrival||'').slice(0,4)).filter(y=>/^\d{4}$/.test(y))])].sort().reverse();let names=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'],total=0;let months=names.map((name,i)=>{let m=String(i+1).padStart(2,'0'),count=entriesInMonth(reportYear,m).length;total+=count;return `<tr><td>${name}</td><td><strong>${count}</strong></td><td><button class="secondary" onclick="reportMonth='${m}';entryReports()">Ver clientes</button></td></tr>`});let list=reportMonth==='all'?db.clients.filter(c=>String(c.arrival||'').startsWith(reportYear+'-')).sort((a,b)=>String(a.arrival).localeCompare(String(b.arrival))):entriesInMonth(reportYear,reportMonth);let missing=db.clients.filter(c=>!c.arrival).length;$('view').innerHTML=reportTabs()+`<div class="panel"><div class="split"><div><h2>Clientes que entraram por mês</h2><p class="muted">Contagem pela data de chegada cadastrada.</p></div><div><label for="reportYear">Ano</label><select id="reportYear" onchange="reportYear=this.value;reportMonth='all';entryReports()">${years.map(y=>`<option value="${y}" ${y===reportYear?'selected':''}>${y}</option>`).join('')}</select></div></div><div class="cards"><div class="card">Total de entradas em ${reportYear}<strong>${total}</strong></div><div class="card">Sem data de chegada<strong>${missing}</strong></div></div><div class="tablewrap"><table><thead><tr><th>Mês</th><th>Clientes</th><th>Ações</th></tr></thead><tbody>${months.join('')}</tbody></table></div></div><div class="panel"><div class="split"><h2>${reportMonth==='all'?'Entradas do ano':'Entradas em '+names[Number(reportMonth)-1]+' de '+reportYear} (${list.length})</h2><div class="actions"><button class="secondary" onclick="reportMonth='all';entryReports()">Ver ano completo</button><button class="secondary" onclick="printEntryReport()">Imprimir / salvar PDF</button><button class="secondary" onclick="exportEntryReport()">Exportar CSV</button></div></div><div class="tablewrap"><table><thead><tr><th>Cliente</th><th>CNPJ</th><th>Chegada</th><th>Ticket</th><th>Etapa</th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${esc(c.fantasy)}</strong></td><td>${esc(c.cnpj)}</td><td>${fmt(c.arrival)}</td><td>${esc(c.ticket||'—')}</td><td>${stageBadge(c.stage)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum cliente no período selecionado.</td></tr>'}</tbody></table></div><p class="muted">Clientes sem data de chegada não entram na contagem mensal. Preencha a data no cadastro para incluí-los.</p></div>`}
function entryList(){return reportMonth==='all'?db.clients.filter(c=>String(c.arrival||'').startsWith(reportYear+'-')).sort((a,b)=>String(a.arrival).localeCompare(String(b.arrival))):entriesInMonth(reportYear,reportMonth)}
function exportEntryReport(){let rows=entryList();if(!rows.length){toast('Nenhum cliente no período selecionado.');return}let data=[['Cliente','CNPJ','Data de chegada','Ticket inicial','Etapa'],...rows.map(c=>[c.fantasy,c.cnpj,fmt(c.arrival),c.ticket,c.stage])];let blob=new Blob(['\uFEFF'+data.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`entradas-${reportYear}${reportMonth==='all'?'':'-'+reportMonth}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printEntryReport(){let rows=entryList(),period=reportMonth==='all'?reportYear:reportMonth+'/'+reportYear;$('printReport').innerHTML=`<h1>Relatório de entrada de clientes</h1><p>Período: ${esc(period)} · Total: <b>${rows.length} clientes</b></p><table><thead><tr><th>Cliente</th><th>CNPJ</th><th>Data de chegada</th><th>Ticket</th><th>Etapa</th></tr></thead><tbody>${rows.map(c=>'<tr>'+[c.fantasy,c.cnpj,fmt(c.arrival),c.ticket,c.stage].map(x=>'<td>'+esc(x||'—')+'</td>').join('')+'</tr>').join('')}</tbody></table>`;window.print()}

function recoveryCandidates(){return [['ps_cs_v1','Registros locais'],['ps_cs_recovery','Cópia de recuperação'],['ps_cs_previous','Cópia anterior'],['ps_cs_before_restore','Cópia anterior à recuperação'],...Object.keys(localStorage).filter(k=>k.startsWith('ps_cs_account_backup_')).map(k=>[k,'Cópia preservada de outro acesso'])].map(([key,label])=>{try{let d=JSON.parse(localStorage.getItem(key)||'null');if(!d||!Array.isArray(d.clients)||!Array.isArray(d.events)||!Array.isArray(d.trainings))return null;return {key,label,data:d}}catch{return null}}).filter(Boolean)}
function inspectRecovery(canRestore){let box=$('recoveryResult'),copies=recoveryCandidates();box.innerHTML=`<div class="notice"><strong>Cópias encontradas neste navegador</strong><p>${copies.length?'':'Nenhuma cópia válida foi encontrada neste navegador.'}</p>${copies.map(x=>`<p>${esc(x.label)}: <b>${x.data.clients.length} cliente(s)</b> · ${x.data.events.length} registro(s) · ${x.data.trainings.length} treinamento(s) <button class="secondary" onclick="downloadRecovery('${x.key}')">Baixar cópia</button> ${canRestore&&x.data.clients.length?`<button onclick="restoreRecovery('${x.key}')">Recuperar clientes desta cópia</button>`:''}</p>`).join('')}${!canRestore?'<p>Entre com a mesma conta ChatGPT para recuperar os dados encontrados. Faça isso no aparelho e navegador em que os dados foram cadastrados.</p>':''}</div>`}
function downloadRecovery(key){let copy=recoveryCandidates().find(x=>x.key===key);if(!copy)return;let blob=new Blob([JSON.stringify(copy.data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='central-cs-copia-recuperacao.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function restoreRecovery(key){let copy=recoveryCandidates().find(x=>x.key===key);if(!copy)return;let existing=new Set(db.clients.map(x=>x.id)),cnpjs=new Set(db.clients.map(x=>x.cnpj).filter(Boolean)),add=copy.data.clients.filter(x=>x&&x.id&&!existing.has(x.id)&&(!x.cnpj||!cnpjs.has(x.cnpj)));let ids=new Set(add.map(x=>x.id));let oldEvents=new Set(db.events.map(x=>x.id)),oldTrainings=new Set(db.trainings.map(x=>x.id));let events=copy.data.events.filter(x=>x&&x.id&&ids.has(x.clientId)&&!oldEvents.has(x.id));let trainings=copy.data.trainings.filter(x=>x&&x.id&&ids.has(x.clientId)&&!oldTrainings.has(x.id));if(!add.length){toast('Nenhum cliente novo foi encontrado nessa cópia.');return}if(!confirm(`Recuperar ${add.length} cliente(s), ${events.length} registro(s) e ${trainings.length} treinamento(s) desta cópia, mantendo os clientes atuais?`))return;localStorage.setItem('ps_cs_before_restore',JSON.stringify(db));db.clients.push(...add);db.events.push(...events);db.trainings.push(...trainings);save();toast(legacyMode?`${add.length} cliente(s) recuperado(s) neste navegador.`:`${add.length} cliente(s) recuperado(s); aguarde a sincronização.`);inspectRecovery(true)}

function legacyAccess(){try{let a=JSON.parse(localStorage.getItem(AUTH)||'null');return a&&typeof a.name==='string'&&typeof a.salt==='string'&&typeof a.hash==='string'?a:null}catch{return null}}
function showLegacyLogin(){let auth=$('auth'),exists=!!legacyAccess();$('app').style.display='none';auth.style.display='block';auth.innerHTML=`<h1 class="auth-brand"><img src="/brand-logo-v1.svg" alt="Central CS" width="300" height="74"></h1><h2>Já tenho cadastro</h2><p>Entre com o nome e a senha do acesso anterior neste navegador.</p><form onsubmit="legacyLogin(event)"><label for="legacyName">Nome</label><input id="legacyName" autocomplete="username" required><label for="legacyPass">Senha</label><input id="legacyPass" type="password" autocomplete="current-password" required><p><button type="submit">Entrar</button></p></form><p id="legacyError" class="error" role="alert"></p>${exists?'':'<p class="hint">Nenhum acesso anterior foi encontrado neste navegador. Use a mesma aba anônima onde você criou o cadastro.</p>'}<hr><h2>Criar novo acesso</h2><p>Para um novo acesso com dados salvos na nuvem, use sua conta ChatGPT.</p><p><a href="/signin-with-chatgpt?return_to=%2F" target="_top">Criar novo acesso com ChatGPT</a></p><p><a href="/signin-with-chatgpt?return_to=%2F" target="_top">Já tenho acesso com ChatGPT</a></p><p><button class="secondary" onclick="inspectRecovery(false)">Procurar cópias neste navegador</button></p><div id="recoveryResult"></div>`}
async function legacyLogin(event){event.preventDefault();let access=legacyAccess();if(!access){$('legacyError').textContent='Não encontrei o cadastro anterior neste navegador. Verifique a aba original.';return}let entered=$('legacyName').value.trim();if(entered.toLocaleLowerCase('pt-BR')!==access.name.trim().toLocaleLowerCase('pt-BR')||await hash($('legacyPass').value,access.salt)!==access.hash){$('legacyError').textContent='Nome ou senha incorretos.';return}sessionStorage.setItem('ps_cs_legacy_session','active');startLegacy()}
function startLegacy(){let access=legacyAccess();if(!access){showLegacyLogin();return}let local;try{local=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}db=local&&Array.isArray(local.clients)&&Array.isArray(local.events)&&Array.isArray(local.trainings)?local:{clients:[],events:[],trainings:[]};db.user=access.name;legacyMode=true;cloudReady=false;$('auth').style.display='none';$('app').style.display='grid';$('who').textContent=access.name;go(['dashboard','clients','alerts','reports','team','account','backup'].includes(preferences.page)?preferences.page:'dashboard');syncMessage('Acesso local: dados somente neste navegador. Faça um backup antes de fechar a aba anônima.');if(!db.clients.length&&recoveryCandidates().some(x=>x.data.clients.length))toast('Há uma cópia com clientes: abra Backup para procurar e recuperar.')}

function openLegacyAccess(){if(localStorage.getItem('ps_cs_pending')==='1'&&!legacyMode){toast('Aguarde a sincronização ou exporte um backup antes de trocar de acesso.');return}showAccountScreen()}

function showAccountScreen(register=false){let auth=$('auth');auth.style.display='block';$('app').style.display='none';auth.innerHTML=`<h1 class="auth-brand"><img src="/brand-logo-v1.svg" alt="Central CS" width="300" height="74"></h1><h2>${register?'Criar novo acesso':'Entrar na sua conta'}</h2><p>${register?'Crie seu usuário e senha. Os registros deste acesso serão salvos no servidor.':'Use seu nome de usuário e senha.'}</p><form onsubmit="submitAccount(event,${register})"><label for="accountUsername">Nome de usuário</label><input id="accountUsername" name="username" autocomplete="username" minlength="3" maxlength="40" required><small>De 3 a 40 caracteres. Pode usar nome, espaços e acentos.</small><label for="accountPassword">Senha</label><input id="accountPassword" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" ${register?'minlength="6"':''} maxlength="256" required>${register?'<label for="accountConfirm">Confirme a senha</label><input id="accountConfirm" type="password" autocomplete="new-password" minlength="6" required><small>Senha com pelo menos 6 caracteres.</small>':''}<p><button type="submit">${register?'Criar acesso':'Entrar'}</button></p><p id="accountError" class="error" role="alert"></p></form><button class="secondary" onclick="showAccountScreen(${!register})">${register?'Já tenho cadastro':'Criar novo acesso'}</button>${!register?'<p><button class="secondary" onclick="showPasswordRecovery()">Esqueci minha senha</button></p>':''}`}
async function submitAccount(event,register){event.preventDefault();let form=event.target,button=form.querySelector('button'),error=$('accountError');error.textContent='';let password=$('accountPassword').value;if(register&&password!==$('accountConfirm').value){error.textContent='As senhas não coincidem.';return}button.disabled=true;try{let response=await fetch('/api/auth/'+(register?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('accountUsername').value.trim(),password})}),result=await response.json().catch(()=>({error:response.status===403?'O serviço bloqueou esta tentativa. Tente novamente pelo navegador.':'O servidor não respondeu corretamente. Tente novamente.'}));if(!response.ok)throw Error(result.error||'Não foi possível entrar.');sessionStorage.removeItem('ps_cs_legacy_session');if(result.recoveryCode){showRecoveryCode(result.recoveryCode,true);return}location.reload()}catch(e){error.textContent=e.message;button.disabled=false}}

async function importBackup(e){let f=e.target.files[0];if(!f)return;try{let incoming=JSON.parse(await f.text());if(!['clients','events','trainings'].every(k=>Array.isArray(incoming[k])))throw Error('Estrutura inválida');let cnpjs=new Set(db.clients.map(c=>c.cnpj)),ids=new Set(db.clients.map(c=>c.id)),add=incoming.clients.filter(c=>c&&typeof c.id==='string'&&typeof c.fantasy==='string'&&/^\d{14}$/.test(c.cnpj)&&!ids.has(c.id)&&!cnpjs.has(c.cnpj));if(!add.length){toast('Nenhum cliente novo encontrado. Os existentes foram mantidos.');return}if(!confirm(`Adicionar ${add.length} cliente(s) sem substituir os cadastros existentes?`))return;localStorage.setItem('ps_cs_before_import',JSON.stringify(db));let addedIds=new Set(add.map(c=>c.id));db.clients.push(...add);let eventIds=new Set(db.events.map(x=>x.id)),trainingIds=new Set(db.trainings.map(x=>x.id));db.events.push(...incoming.events.filter(x=>x&&addedIds.has(x.clientId)&&!eventIds.has(x.id)));db.trainings.push(...incoming.trainings.filter(x=>x&&addedIds.has(x.clientId)&&!trainingIds.has(x.id)));save();go('clients');toast(`${add.length} cliente(s) adicionado(s).`)}catch(error){alert('Não foi possível importar: '+error.message)}finally{e.target.value=''}}

async function maybeInitializeTeam(){if(legacyMode||cloudConflict||localStorage.getItem('ps_cs_pending')==='1')return;try{let response=await fetch('/api/team',{cache:'no-store'});if(!response.ok)return;let team=await response.json();if(team.isAdmin&&!team.ready){let created=await fetch('/api/team',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'initialize'})});if(created.ok){location.reload();return}let result=await created.json();syncMessage(result.error||'Não foi possível ativar a equipe. Use a aba Equipe.')}}catch{}}
async function renderTeam(){if(legacyMode){$('view').innerHTML='<section class="panel"><h2>Equipe</h2><p>O acesso antigo deste navegador é local. Entre com um usuário e senha da nova versão para usar a base compartilhada.</p></section>';return}$('view').innerHTML='<section class="panel"><p>Carregando equipe…</p></section>';try{let response=await fetch('/api/team',{cache:'no-store'}),team=await response.json();if(!response.ok)throw Error(team.error||'Não foi possível carregar a equipe.');if(current!=='team')return;$('view').innerHTML=`<section class="panel"><h2>Base compartilhada da equipe</h2><p>Cada pessoa usa seu próprio usuário e senha. Somente membros aprovados acessam os clientes, treinamentos, históricos e relatórios compartilhados.</p>${team.isAdmin?`<p><span class="tag ok">Administrador</span></p>${!team.ready?'<button onclick="teamAction(&quot;initialize&quot;)">Ativar base compartilhada com meus cadastros</button>':''}`:team.approved?'<p class="tag ok">Seu acesso à equipe está aprovado.</p>':team.ready?team.requested?'<p class="tag soon">Solicitação enviada. Aguarde a aprovação de juliocnovais.</p><button class="secondary" onclick="refreshPage()">Verificar aprovação</button>':'<p>Seus dados individuais continuam separados até a aprovação.</p><button onclick="teamAction(&quot;request&quot;)">Solicitar acesso à equipe</button>':'<p>A equipe estará disponível após o primeiro acesso do administrador juliocnovais.</p>'}</section>${team.isAdmin&&team.ready?`<section class="panel"><h2>Solicitações pendentes (${team.pending.length})</h2>${team.pending.map(p=>`<div class="notice split"><strong>${esc(p.name)}</strong><div class="actions"><button onclick="teamAction('approve','${p.id}')">Aprovar</button><button class="secondary" onclick="teamAction('reject','${p.id}')">Recusar</button></div></div>`).join('')||'<p class="muted">Nenhuma solicitação pendente.</p>'}</section><section class="panel"><h2>Membros (${team.members.length})</h2>${team.members.map(m=>`<div class="notice split"><div><strong>${esc(m.name)}</strong> · ${m.role==='admin'?'Administrador':'Membro'}</div>${m.role!=='admin'?`<button class="secondary" onclick="teamAction('revoke','${m.id}')">Remover acesso</button>`:''}</div>`).join('')}</section>`:''}<section class="panel"><h2>Preservação dos cadastros</h2><p>Os registros individuais anteriores permanecem guardados. As informações da base compartilhada são copiadas inicialmente da conta do administrador. Cadastros locais ou de outras contas podem ser acrescentados por importação, sem substituir clientes existentes.</p><p class="hint">Alterações de outro computador aparecem ao atualizar a página. Se houver edição simultânea, o sistema avisa antes de sobrescrever dados.</p></section>`}catch(error){if(current==='team')$('view').innerHTML='<section class="panel"><p>'+esc(error.message)+'</p><button onclick="renderTeam()">Tentar novamente</button></section>'}}
async function teamAction(action,targetId){if(['approve','revoke','reject'].includes(action)&&!confirm(action==='approve'?'Aprovar acesso deste usuário a todos os registros da equipe?':action==='revoke'?'Remover o acesso deste usuário à base compartilhada?':'Recusar esta solicitação?'))return;if(action==='initialize'){await queueCloud();if(localStorage.getItem('ps_cs_pending')==='1'){toast('Sincronize os dados ou exporte uma cópia antes de ativar a equipe.');return}}try{let response=await fetch('/api/team',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,targetId})}),result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível atualizar a equipe.');if(action==='initialize'){location.reload();return}toast(action==='request'?'Solicitação enviada.':'Equipe atualizada.');renderTeam()}catch(error){toast(error.message)}}

async function loadResponsibleOptions(){let list=$('csResponsibleList');if(!list)return;list.innerHTML='<option value="'+esc(db.user||'')+'"></option>';if(legacyMode)return;try{let response=await fetch('/api/team',{cache:'no-store'});if(!response.ok)return;let team=await response.json();if($('csResponsibleList')!==list)return;list.innerHTML=[...new Set([db.user,...team.responsibleNames||[]].filter(Boolean))].map(name=>'<option value="'+esc(name)+'"></option>').join('')}catch{}}

async function fetchTimed(url,options={}){let controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{return await fetch(url,{...options,signal:controller.signal})}catch(error){throw Error(error.name==='AbortError'?'O servidor demorou para responder. Seus dados locais foram preservados.':error.message)}finally{clearTimeout(timer)}}
function matchesResponsible(c){return !preferences.responsible||(preferences.responsible==='__none__'?!c.responsible:c.responsible===preferences.responsible)}
function responsibleFilterOptions(){let names=[...new Set([db.user,...db.clients.map(c=>c.responsible)].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));return [['','Todos os responsáveis'],['__none__','Sem responsável'],...names.map(n=>[n,n])].map(([value,label])=>`<option value="${esc(value)}" ${preferences.responsible===value?'selected':''}>${esc(label)}</option>`).join('')}
function clientDateMessage(c){for(const key of dateFields){let v=c[key];if(v&&(!/^\d{4}-\d{2}-\d{2}$/.test(v)||isNaN(new Date(v+'T12:00:00Z'))||new Date(v+'T12:00:00Z').toISOString().slice(0,10)!==v))return 'Confira a data de '+labels[key]+'.'}for(const key of ['contractPortal','contractSigned','onboarding','implementation','activationDate'])if(c.arrival&&c[key]&&c[key]<c.arrival)return labels[key]+': a data não pode ser anterior à chegada.';if(c.implementation&&c.activationDate&&c.activationDate<c.implementation)return 'A ativação não pode ser anterior ao início da implantação.';if(c.implementation&&c.followupDate&&c.followupDate<c.implementation)return 'O follow-up não pode ser anterior ao início da implantação.';return ''}
async function loadServerBackups(cursor='',append=false){let box=$('serverBackups');if(!box)return;if(!append)box.innerHTML='<p>Carregando cópias automáticas…</p>';try{let response=await fetchTimed('/api/history'+(cursor?'?cursor='+encodeURIComponent(cursor):'')),result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível carregar as cópias.');if($('serverBackups')!==box)return;let html=result.items.map(item=>`<div class="notice split"><div><strong>${new Date(item.at).toLocaleString('pt-BR')}</strong> · ${item.clients} cliente(s)<br><small>Antes de uma alteração por ${esc(item.actor)} · ${esc(item.reason)}</small></div><button class="secondary" onclick="restoreServerBackup('${encodeURIComponent(item.key)}')">Restaurar esta cópia</button></div>`).join('');if(!append)box.innerHTML='<p class="hint">As cópias são criadas antes de cada salvamento nesta versão. Antes de restaurar, outra cópia dos dados atuais é guardada automaticamente. Somente o administrador restaura a base da equipe.</p>';box.querySelector('.more-backups')?.remove();box.insertAdjacentHTML('beforeend',html||(append?'':'<p>Nenhuma cópia automática disponível ainda. Ela aparecerá após a próxima alteração de dados já salvos.</p>'));if(result.cursor)box.insertAdjacentHTML('beforeend',`<button class="secondary more-backups" onclick="loadServerBackups(decodeURIComponent('${encodeURIComponent(result.cursor)}'),true)">Carregar mais</button>`)}catch(error){box.innerHTML='<p class="error">'+esc(error.message)+'</p>'}}
async function restoreServerBackup(encodedKey){await queueCloud();if(localStorage.getItem('ps_cs_pending')==='1'){toast('Salve ou exporte as alterações locais antes de restaurar.');return}if(!confirm('Restaurar os clientes, históricos e treinamentos desta cópia? Os dados atuais serão guardados em outro backup automático.'))return;try{let response=await fetchTimed('/api/history/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:decodeURIComponent(encodedKey),etag:cloudEtag})}),result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível restaurar.');location.reload()}catch(error){toast(error.message)}}
function auditValue(value){return value==null?'—':typeof value==='object'?JSON.stringify(value,null,2):String(value)}
async function showServerAudit(clientId,cursor='',append=false){if(legacyMode){toast('O histórico verificado por usuário está disponível no acesso com servidor.');return}if(!append)openDialog('Alterações por usuário','<div id="serverAudit"><p>Carregando histórico…</p></div>');let box=$('serverAudit');if(!box)return;try{let response=await fetchTimed('/api/audit?clientId='+encodeURIComponent(clientId)+(cursor?'&cursor='+encodeURIComponent(cursor):'')),result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível carregar o histórico.');if($('serverAudit')!==box)return;if(!append)box.innerHTML='<p class="hint">Registros confirmados pelo servidor a partir desta versão. As alterações locais ainda não sincronizadas não aparecem aqui.</p>';box.querySelector('.more-audit')?.remove();let html=result.items.map(item=>`<div class="panel"><strong>${esc(item.kind)}</strong><p>${new Date(item.at).toLocaleString('pt-BR')} · <b>${esc(item.actor)}</b></p>${item.changes.map(change=>`<details><summary>${esc(labels[change.field]||({events:'Histórico de contatos',trainings:'Treinamentos'}[change.field])||change.field)}</summary><div class="grid"><div><small>Antes</small><pre class="audit-value">${esc(auditValue(change.before))}</pre></div><div><small>Depois</small><pre class="audit-value">${esc(auditValue(change.after))}</pre></div></div></details>`).join('')}</div>`).join('');box.insertAdjacentHTML('beforeend',html||(!append?'<p>Nenhuma alteração registrada no servidor nesta versão para este cliente.</p>':''));if(result.cursor)box.insertAdjacentHTML('beforeend',`<button class="secondary more-audit" onclick="showServerAudit('${clientId}',decodeURIComponent('${encodeURIComponent(result.cursor)}'),true)">Carregar mais</button>`)}catch(error){box.innerHTML='<p class="error">'+esc(error.message)+'</p>'}}
function renderAccount(){$('view').innerHTML=`<section class="panel"><h2>Minha conta</h2><p>Usuário: <strong>${esc(db.user.includes('@')?'Minha conta':db.user)}</strong></p>${accountAuthKind==='password'&&!legacyMode?'<h2>Recuperação de senha</h2><p>Gere um código e guarde-o em um local seguro fora deste site. Ele permitirá redefinir sua senha sem criar outra conta.</p><p>Gerar um novo código invalida o anterior. Após usar um código para trocar a senha, gere outro ao entrar novamente.</p><button onclick="generateRecoveryCode()">Gerar código de recuperação</button><div id="accountRecoveryResult"></div>':'<p>Esta recuperação está disponível para contas criadas com usuário e senha no servidor.</p>'}</section>`}
function recoveryCodeContent(code,registration=false){return `<h2>Guarde seu código de recuperação</h2><p>Este código permite redefinir a senha. Copie-o e guarde fora do site. Ele não será exibido novamente.</p><pre class="recovery-code">${esc(code)}</pre><p class="hint">Quem tiver este código e seu usuário poderá trocar sua senha. Não o compartilhe com a equipe.</p>${registration?'<button onclick="location.reload()">Já guardei, continuar para a Central</button>':''}`}
function showRecoveryCode(code,registration=false){if(registration)$('auth').innerHTML='<h1>Acesso criado</h1>'+recoveryCodeContent(code,true);else $('accountRecoveryResult').innerHTML=recoveryCodeContent(code)}
async function generateRecoveryCode(){if(!confirm('Gerar um novo código de recuperação? O código anterior deixará de funcionar.'))return;try{let response=await fetchTimed('/api/recovery/generate',{method:'POST'}),result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível gerar o código.');showRecoveryCode(result.recoveryCode)}catch(error){toast(error.message)}}
function showPasswordRecovery(){$('auth').innerHTML='<h1>Recuperar senha</h1><p>Informe seu usuário e o código de recuperação que você guardou.</p><form onsubmit="resetPassword(event)"><label for="recoveryUser">Nome de usuário</label><input id="recoveryUser" autocomplete="username" required maxlength="40"><label for="recoveryCode">Código de recuperação</label><input id="recoveryCode" autocomplete="off" required><label for="recoveryPassword">Nova senha</label><input id="recoveryPassword" type="password" autocomplete="new-password" minlength="6" maxlength="256" required><label for="recoveryConfirm">Confirme a nova senha</label><input id="recoveryConfirm" type="password" autocomplete="new-password" minlength="6" maxlength="256" required><p><button type="submit">Redefinir senha</button></p><p id="recoveryError" class="error" role="alert"></p></form><button class="secondary" onclick="showAccountScreen()">Voltar ao login</button><p class="hint">Contas antigas devem gerar um código em Minha conta enquanto ainda têm acesso. Não é possível recuperar sem senha nem código por esta opção.</p>'}
async function resetPassword(event){event.preventDefault();let error=$('recoveryError'),button=event.target.querySelector('button');if($('recoveryPassword').value!==$('recoveryConfirm').value){error.textContent='As senhas não coincidem.';return}button.disabled=true;try{let response=await fetchTimed('/api/recovery/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('recoveryUser').value,code:$('recoveryCode').value,password:$('recoveryPassword').value})}),result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível redefinir a senha.');showAccountScreen();$('accountError').textContent='Senha alterada. Entre com a nova senha e gere outro código de recuperação em Minha conta.'}catch(e){error.textContent=e.message;button.disabled=false}}

let reportMode='consolidated';
function reportTabs(){return `<div class="client-tabs"><button class="${reportMode==='consolidated'?'active':''}" onclick="reports('consolidated')">Resumo mensal</button><button class="${reportMode==='entries'?'active':''}" onclick="reports('entries')">Entradas por ano</button></div>`}
function reports(mode=reportMode){reportMode=mode;if(mode==='entries')entryReports();else consolidatedReport()}
function monthlyMetrics(clients,month,asOf){const monthOf=s=>String(s||'').slice(0,7);let implant=c=>(c.implementation||c.implementationConfirmed)&&c.activationStatus!=='Ativada'&&c.stage!=='Concluído';let late=c=>{if(!implant(c)||!c.implementation||c.followupDone)return false;let d=new Date(c.implementation+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+7);return d.toISOString().slice(0,10)<=asOf};let selected=clients.filter(c=>monthOf(c.arrival)===month||monthOf(c.activationDate)===month&&c.activationStatus==='Ativada'||implant(c));let groups=[...new Set(clients.map(c=>c.responsible||''))].sort().map(name=>{let list=clients.filter(c=>(c.responsible||'')===name);return {name:name||'Sem responsável',arrivals:list.filter(c=>monthOf(c.arrival)===month).length,activations:list.filter(c=>c.activationStatus==='Ativada'&&monthOf(c.activationDate)===month).length,implementation:list.filter(implant).length,followups:list.filter(late).length}});let totals={arrivals:0,activations:0,implementation:0,followups:0};for(let g of groups)for(let key of Object.keys(totals))totals[key]+=g[key];return {groups,totals,clients:selected}}
function consolidatedData(){let month=preferences.consolidatedMonth||activationToday().slice(0,7),responsible=preferences.reportResponsible||'';let list=db.clients.filter(c=>!responsible||(responsible==='__none__'?!c.responsible:c.responsible===responsible));return {month,responsible,...monthlyMetrics(list,month,activationToday())}}
function consolidatedReport(){let result=consolidatedData(),all=[...new Set(db.clients.map(c=>c.responsible).filter(Boolean))].sort();$('view').innerHTML=reportTabs()+`<section class="panel"><h2>Resumo mensal de CS</h2><div class="toolbar"><div><label for="consolidatedMonth">Mês e ano</label><input id="consolidatedMonth" type="month" required value="${result.month}" onchange="preferences.consolidatedMonth=this.value||activationToday().slice(0,7);persistPreferences();consolidatedReport()"></div><div><label for="reportResponsible">Responsável CS</label><select id="reportResponsible" onchange="preferences.reportResponsible=this.value;persistPreferences();consolidatedReport()">${[['','Todos'],['__none__','Sem responsável'],...all.map(x=>[x,x])].map(([key,name])=>`<option value="${esc(key)}" ${result.responsible===key?'selected':''}>${esc(name)}</option>`).join('')}</select></div><button class="secondary" onclick="exportConsolidated()">Exportar CSV</button><button class="secondary" onclick="printConsolidated()">Imprimir / salvar PDF</button></div><p class="hint">Entradas e ativações correspondem ao mês selecionado. Implantações e follow-ups mostram as pendências atuais, não uma posição histórica.</p><div class="cards report-cards"><div class="card">Entradas no mês<strong>${result.totals.arrivals}</strong></div><div class="card">Ativações no mês<strong>${result.totals.activations}</strong></div><div class="card">Em implantação hoje<strong>${result.totals.implementation}</strong></div><div class="card">Follow-ups vencidos/hoje<strong>${result.totals.followups}</strong></div></div></section><section class="panel"><h2>Resultado por responsável</h2>${consolidatedTable(result)}<p class="hint">Sem data de chegada: ${db.clients.filter(c=>!c.arrival).length} · Em implantação sem data de início: ${db.clients.filter(c=>c.implementationConfirmed&&!c.implementation&&c.activationStatus!=='Ativada').length}. Complete essas datas para melhorar os indicadores.</p></section>`}
function consolidatedTable(result){return '<div class="tablewrap"><table><thead><tr><th>Responsável</th><th>Entradas</th><th>Ativações</th><th>Em implantação hoje</th><th>Follow-ups vencidos/hoje</th></tr></thead><tbody>'+result.groups.map(g=>'<tr>'+[g.name,g.arrivals,g.activations,g.implementation,g.followups].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'<tr>'+['Total',result.totals.arrivals,result.totals.activations,result.totals.implementation,result.totals.followups].map(v=>'<td><strong>'+esc(v)+'</strong></td>').join('')+'</tr></tbody></table></div>'}
function exportConsolidated(){let result=consolidatedData(),data=[['Mês','Responsável','Entradas','Ativações','Em implantação hoje','Follow-ups vencidos/hoje'],...result.groups.map(g=>[result.month,g.name,g.arrivals,g.activations,g.implementation,g.followups]),[result.month,'TOTAL',result.totals.arrivals,result.totals.activations,result.totals.implementation,result.totals.followups]];let blob=new Blob(['\uFEFF'+data.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='relatorio-cs-'+result.month+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printConsolidated(){let result=consolidatedData();$('printReport').innerHTML='<h1>Relatório mensal de CS</h1><p>Período: '+esc(result.month.slice(5)+'/'+result.month.slice(0,4))+' · Emissão: '+fmt(activationToday())+'</p><p>Entradas e ativações no mês. Implantações e follow-ups são pendências atuais.</p>'+consolidatedTable(result);window.print()}
setInterval(async()=>{if(!cloudReady||legacyMode||syncing||cloudConflict||document.visibilityState!=='visible'||$('modal').open||localStorage.getItem('ps_cs_pending')==='1')return;try{let response=await fetchTimed('/api/state',{cache:'no-store'});if(!response.ok)return;let remote=await response.json();if(localStorage.getItem('ps_cs_pending')==='1'||$('modal').open||syncing)return;if(remote.scopeId!==localStorage.getItem('ps_cs_local_owner')){location.reload();return}if(remote.etag===cloudEtag||!remote.data)return;localStorage.setItem('ps_cs_autorefresh_backup',JSON.stringify(db));db=remote.data;db.user=remote.name||db.user;cloudEtag=remote.etag;localStorage.setItem(KEY,JSON.stringify(db));localStorage.setItem('ps_cs_cloud_etag',cloudEtag);render();syncMessage('✓ Atualizado com os registros do servidor às '+new Date().toLocaleTimeString('pt-BR'))}catch{}},45000);

function stageClass(stage){return ({'Entrada':'stage-entry','Contrato':'stage-contract','Onboarding':'stage-onboarding','Treinamento':'stage-onboarding','Implantação':'stage-implementation','Ativação de carteira':'stage-done','Concluído':'stage-done','Ativada':'stage-done'})[stage]||'stage-entry'}
function stageBadge(stage,label=stage){return '<span class="tag '+stageClass(stage)+'">'+esc(label||'—')+'</span>'}
function categoryStageClass(category){return ({contract:'stage-contract',implementation:'stage-implementation',activation:'stage-done'})[category]||'stage-entry'}

function loadingMarkup(){return `<div class="cs-loading robot-loading" role="status" aria-live="polite" aria-busy="true"><h1 class="auth-brand"><img src="/brand-logo-v1.svg" alt="Central CS" width="300" height="74"></h1><div class="robot-stage" aria-hidden="true"><div class="robot-track"></div><div class="robot-runner"><div class="robot-frame"><img src="/cs-robot-run-v2.png" class="robot-sprite" alt="" width="2172" height="724"></div></div><svg class="robot-ticket" viewBox="0 0 90 65"><path d="M8 8h74v14a10 10 0 0 0 0 20v14H8V42a10 10 0 0 0 0-20z" fill="white" stroke="#10b7b7" stroke-width="3"/><circle cx="29" cy="32" r="10" fill="#10b7b7"/><path d="m24 32 4 4 7-9" fill="none" stroke="white" stroke-width="2.5" stroke-linecap="round"/><path d="M47 24h21M47 33h18M47 42h14" stroke="#b6d3e3" stroke-width="3" stroke-linecap="round"/></svg><div class="robot-party"><i>✦</i><i>✧</i><i>✦</i></div></div><p class="loading-caption">Só um instante…<br><span>esse ticket tá ligeiro!</span></p><small>Carregando seus registros</small></div>`}
